CREATE TABLE sos_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),neighborhood_id uuid REFERENCES neighborhoods(id),property_id uuid NOT NULL REFERENCES properties(id),requested_by_user_id uuid NOT NULL REFERENCES app_users(id),contact_user_id uuid NOT NULL REFERENCES app_users(id),incident_id uuid NOT NULL UNIQUE REFERENCES incidents(id),severity alert_severity NOT NULL DEFAULT 'critical',occurrence text NOT NULL CHECK(length(occurrence) BETWEEN 3 AND 2000),location geography(Point,4326) NOT NULL,location_accuracy_m numeric CHECK(location_accuracy_m IS NULL OR location_accuracy_m>=0),status text NOT NULL DEFAULT 'open' CHECK(status IN('open','acknowledged','closed','cancelled')),public_integration_status text NOT NULL DEFAULT 'not_configured' CHECK(public_integration_status IN('not_configured','authorized_future')),created_at timestamptz NOT NULL DEFAULT now(),acknowledged_at timestamptz,acknowledged_by_user_id uuid REFERENCES app_users(id),closed_at timestamptz);
CREATE INDEX idx_sos_scope_status ON sos_requests(organization_id,property_id,status,created_at DESC);
CREATE TABLE sos_evidence(sos_id uuid NOT NULL REFERENCES sos_requests(id) ON DELETE CASCADE,evidence_id uuid NOT NULL REFERENCES evidence(id),linked_by_user_id uuid NOT NULL REFERENCES app_users(id),linked_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(sos_id,evidence_id));
ALTER TABLE sos_requests ENABLE ROW LEVEL SECURITY;ALTER TABLE sos_evidence ENABLE ROW LEVEL SECURITY;
CREATE POLICY sos_scope_read ON sos_requests FOR SELECT TO authenticated USING(app_has_scope_access(organization_id,neighborhood_id,property_id));CREATE POLICY sos_evidence_scope_read ON sos_evidence FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM sos_requests s WHERE s.id=sos_evidence.sos_id AND app_has_scope_access(s.organization_id,s.neighborhood_id,s.property_id)));
REVOKE INSERT,UPDATE,DELETE ON sos_requests,sos_evidence FROM authenticated,anonymous;GRANT SELECT ON sos_requests,sos_evidence TO authenticated;
CREATE OR REPLACE FUNCTION start_ifarm_sos(p_property_id uuid,p_occurrence text,p_latitude double precision DEFAULT NULL,p_longitude double precision DEFAULT NULL,p_accuracy_m numeric DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,auth AS $$ DECLARE v_org uuid;v_neigh uuid;v_centroid geography(Point,4326);v_location geography(Point,4326);v_user uuid:=app_current_user_id();v_incident uuid;v_sos uuid;BEGIN SELECT organization_id,neighborhood_id,centroid INTO v_org,v_neigh,v_centroid FROM properties WHERE id=p_property_id;IF NOT FOUND THEN RAISE EXCEPTION 'property_not_found';END IF;IF v_user IS NULL OR NOT app_has_scope_access(v_org,v_neigh,p_property_id) THEN RAISE EXCEPTION 'property_access_required';END IF;IF COALESCE(btrim(p_occurrence),'')='' OR length(btrim(p_occurrence))<3 OR length(btrim(p_occurrence))>2000 THEN RAISE EXCEPTION 'invalid_occurrence';END IF;IF(p_latitude IS NULL)<>(p_longitude IS NULL) THEN RAISE EXCEPTION 'latitude_longitude_pair_required';END IF;IF p_latitude IS NOT NULL THEN IF p_latitude NOT BETWEEN -90 AND 90 OR p_longitude NOT BETWEEN -180 AND 180 THEN RAISE EXCEPTION 'invalid_coordinates';END IF;v_location:=ST_SetSRID(ST_MakePoint(p_longitude,p_latitude),4326)::geography;ELSE v_location:=v_centroid;END IF;IF v_location IS NULL THEN RAISE EXCEPTION 'location_required';END IF;INSERT INTO incidents(organization_id,neighborhood_id,property_id,title,severity,status,responsible_user_id,created_by_user_id,summary,updated_at) VALUES(v_org,v_neigh,p_property_id,'iFarm SOS - pedido de assistência','critical','open',NULL,v_user,'Pedido de assistência iniciado pelo usuário. '||btrim(p_occurrence)||' Este registro não presume crime nem integração com autoridade pública.',now()) RETURNING id INTO v_incident;INSERT INTO incident_actions(organization_id,incident_id,actor_user_id,action,note,details) VALUES(v_org,v_incident,v_user,'created',btrim(p_occurrence),jsonb_build_object('source','ifarm_sos','publicIntegration','not_configured'));INSERT INTO sos_requests(organization_id,neighborhood_id,property_id,requested_by_user_id,contact_user_id,incident_id,occurrence,location,location_accuracy_m,status,public_integration_status) VALUES(v_org,v_neigh,p_property_id,v_user,v_user,v_incident,btrim(p_occurrence),v_location,p_accuracy_m,'open','not_configured') RETURNING id INTO v_sos;RETURN v_sos;END $$;GRANT EXECUTE ON FUNCTION start_ifarm_sos(uuid,text,double precision,double precision,numeric) TO authenticated;
CREATE OR REPLACE FUNCTION acknowledge_ifarm_sos(p_sos_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,auth AS $$ DECLARE v_org uuid;v_neigh uuid;v_prop uuid;v_incident uuid;v_user uuid:=app_current_user_id();BEGIN SELECT organization_id,neighborhood_id,property_id,incident_id INTO v_org,v_neigh,v_prop,v_incident FROM sos_requests WHERE id=p_sos_id;IF NOT FOUND THEN RAISE EXCEPTION 'sos_not_found';END IF;IF NOT app_can_manage_evidence_scope(v_org,v_neigh,v_prop) THEN RAISE EXCEPTION 'sos_acknowledgement_required';END IF;UPDATE sos_requests SET status='acknowledged',acknowledged_at=COALESCE(acknowledged_at,now()),acknowledged_by_user_id=COALESCE(acknowledged_by_user_id,v_user) WHERE id=p_sos_id AND status='open';UPDATE incidents SET responsible_user_id=COALESCE(responsible_user_id,v_user),status=CASE WHEN status='open' THEN 'investigating' ELSE status END,updated_at=now() WHERE id=v_incident AND status<>'closed';INSERT INTO incident_actions(organization_id,incident_id,actor_user_id,action,note,details) VALUES(v_org,v_incident,v_user,'claimed','SOS reconhecido',jsonb_build_object('sosId',p_sos_id));RETURN true;END $$;GRANT EXECUTE ON FUNCTION acknowledge_ifarm_sos(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION close_ifarm_sos(p_sos_id uuid,p_note text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,auth AS $$ DECLARE v_org uuid;v_neigh uuid;v_prop uuid;v_incident uuid;v_user uuid:=app_current_user_id();BEGIN SELECT organization_id,neighborhood_id,property_id,incident_id INTO v_org,v_neigh,v_prop,v_incident FROM sos_requests WHERE id=p_sos_id;IF NOT FOUND THEN RAISE EXCEPTION 'sos_not_found';END IF;IF NOT app_can_manage_evidence_scope(v_org,v_neigh,v_prop) THEN RAISE EXCEPTION 'sos_management_required';END IF;IF COALESCE(btrim(p_note),'')='' THEN RAISE EXCEPTION 'closure_note_required';END IF;UPDATE sos_requests SET status='closed',closed_at=now() WHERE id=p_sos_id AND status<>'cancelled';INSERT INTO incident_actions(organization_id,incident_id,actor_user_id,action,note,details) VALUES(v_org,v_incident,v_user,'note_added',btrim(p_note),jsonb_build_object('sosId',p_sos_id,'sosStatus','closed'));RETURN true;END $$;GRANT EXECUTE ON FUNCTION close_ifarm_sos(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION link_evidence_to_sos(p_sos_id uuid,p_evidence_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,auth AS $$ DECLARE v_org uuid;v_neigh uuid;v_prop uuid;v_e_org uuid;v_e_neigh uuid;v_e_prop uuid;v_user uuid:=app_current_user_id();BEGIN SELECT organization_id,neighborhood_id,property_id INTO v_org,v_neigh,v_prop FROM sos_requests WHERE id=p_sos_id;IF NOT FOUND THEN RAISE EXCEPTION 'sos_not_found';END IF;SELECT e.organization_id,s.neighborhood_id,s.property_id INTO v_e_org,v_e_neigh,v_e_prop FROM evidence e CROSS JOIN LATERAL resolve_evidence_scope(e.incident_id,e.event_id,e.recording_id) s WHERE e.id=p_evidence_id;IF NOT FOUND THEN RAISE EXCEPTION 'evidence_not_found';END IF;IF v_org<>v_e_org OR v_prop IS DISTINCT FROM v_e_prop THEN RAISE EXCEPTION 'sos_evidence_scope_mismatch';END IF;IF NOT app_has_scope_access(v_org,v_neigh,v_prop) THEN RAISE EXCEPTION 'sos_access_required';END IF;INSERT INTO sos_evidence(sos_id,evidence_id,linked_by_user_id) VALUES(p_sos_id,p_evidence_id,v_user) ON CONFLICT DO NOTHING;RETURN true;END $$;GRANT EXECUTE ON FUNCTION link_evidence_to_sos(uuid,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION get_ifarm_sos_feed() RETURNS TABLE(id uuid,property_id uuid,property_name text,requested_by_user_id uuid,requested_by_name text,incident_id uuid,occurrence text,severity alert_severity,status text,latitude double precision,longitude double precision,location_accuracy_m numeric,public_integration_status text,created_at timestamptz,acknowledged_at timestamptz,closed_at timestamptz,evidence_count bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO public,auth AS $$ SELECT s.id,s.property_id,p.name,s.requested_by_user_id,u.full_name,s.incident_id,s.occurrence,s.severity,s.status,ST_Y(s.location::geometry),ST_X(s.location::geometry),s.location_accuracy_m,s.public_integration_status,s.created_at,s.acknowledged_at,s.closed_at,(SELECT count(*) FROM sos_evidence se WHERE se.sos_id=s.id) FROM sos_requests s JOIN properties p ON p.id=s.property_id JOIN app_users u ON u.id=s.requested_by_user_id WHERE app_has_scope_access(s.organization_id,s.neighborhood_id,s.property_id) ORDER BY s.created_at DESC $$;GRANT EXECUTE ON FUNCTION get_ifarm_sos_feed() TO authenticated;
